package dev.gbppimentel.snapcompanion;
import android.content.*;import android.net.Uri;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class UiShellTest {
 @Test public void openingKeepsAutomaticPolicyAndDoesNotRewriteLegacyNotebook()throws Exception{Context c=RuntimeEnvironment.getApplication();String legacy="legacy notebook unchanged";c.getSharedPreferences("snap",0).edit().putString("progress",legacy).putBoolean("edenAutoLink",false).putBoolean("autoGallery",false).commit();try(var controller=Robolectric.buildActivity(MainActivity.class).setup()){assertTrue(c.getSharedPreferences("snap",0).getBoolean("edenAutoLink",false));assertTrue(c.getSharedPreferences("snap",0).getBoolean("autoGallery",false));assertEquals(legacy,c.getSharedPreferences("snap",0).getString("progress",""));}}
 @Test public void webShellCannotReadArbitraryFilesOrLoadRemoteSites()throws Exception{try(var controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=controller.get();assertNull(a.resource(Uri.parse("file:///android_asset/ui/style.css")));for(String url:new String[]{"file:///data/user/0/private.xml","https://example.com","https://snap.companion.invalid/photo/unknown","content://arbitrary"})assertEquals(-1,a.resource(Uri.parse(url)).getData().read());}}
 @Test public void legacyManualCourseIsNotPublishedAsLiveContext()throws Exception{Context c=RuntimeEnvironment.getApplication();c.getSharedPreferences("snap",0).edit().putString("progress","{\"course\":\"park-night\",\"level\":3}").commit();EdenLinkService.gameRunning=false;EdenLinkService.gameVisible=false;try(var controller=Robolectric.buildActivity(MainActivity.class).setup()){var snap=controller.get().snapshot();assertEquals("",snap.getString("course"));assertEquals(0,snap.getInt("level"));assertEquals("waiting",snap.getString("phase"));assertFalse(snap.has("album"));}}
}
